/**
 * Firestore Database Seeder for LifeSync.
 *
 * Populates Firestore with rich, realistic dummy data:
 * - User Profile (Daily goals, routine times, preferences)
 * - 5 Realistic Habits
 * - WINDOW_DAYS days of Habit Completion Logs (with natural streaks and circadian patterns)
 * - WINDOW_DAYS days of Health Metrics (Sleep hours, Water intake, Step counts)
 * - WINDOW_DAYS days of Multimodal Food Logs (Calories, Macros, Condition, Health Tips)
 * - Pre-computed AI Recommendations generated by the trained ML model
 *
 * Usage:
 *   npx ts-node --transpile-only src/seed/seedDatabase.ts [--uid=CUSTOM_UID] [--project=PROJECT_ID]
 *   npx ts-node --transpile-only src/seed/seedDatabase.ts --email=someone@example.com [--project=PROJECT_ID]
 *
 * --email targets a REAL existing user (resolved to their UID via Firebase Auth) instead of the
 * demo-user-123 default. In that mode, the user's existing profile fields (displayName, email,
 * goals, etc.) are left untouched — only `createdAt` (their "joined" date) is merged in, backdated
 * to just before the seeded window, so the seeded history doesn't predate account creation.
 * This writes to whatever Firestore project your credentials point at (real production data if
 * you're authenticated against the live project) — double check GCLOUD_PROJECT / your
 * GOOGLE_APPLICATION_CREDENTIALS before running against anything but the emulator.
 */

import { initializeApp } from 'firebase-admin/app';
import { getFirestore, Timestamp } from 'firebase-admin/firestore';
import { getAuth } from 'firebase-admin/auth';
import { recommendHourWithModel, CANDIDATE_HOURS, type MlContext } from '../ml/mlRecommender';
import { hourKernelSuccessRate, RECENCY_DECAY, type HourlyAttempt } from '../ml/historicalRate';

// If FIRESTORE_EMULATOR_HOST is set, it connects locally.
if (!process.env.FIRESTORE_EMULATOR_HOST && !process.env.GOOGLE_APPLICATION_CREDENTIALS) {
  process.env.FIRESTORE_EMULATOR_HOST = process.env.FIRESTORE_EMULATOR_HOST || '127.0.0.1:8080';
}

const app = initializeApp({ projectId: process.env.GCLOUD_PROJECT || 'demo-lifesync' });
const db = getFirestore();

// How many days of habit/health/food history to seed — "3 weeks" per the request that prompted
// --email mode; kept as a single constant so every collection stays in sync.
const WINDOW_DAYS = 21;

// Parse CLI arguments
const args = process.argv.slice(2);
let targetUid = 'demo-user-123';
let targetEmail: string | null = null;
for (const arg of args) {
  if (arg.startsWith('--uid=')) targetUid = arg.split('=')[1];
  if (arg.startsWith('--email=')) targetEmail = arg.split('=')[1];
}

console.log('====================================================');
console.log(' LifeSync Firestore Database Seeder');
console.log('====================================================');
console.log(`Firestore Host:  ${process.env.FIRESTORE_EMULATOR_HOST || 'Live Firebase Cloud'}`);

function formatDate(d: Date): string {
  return d.toISOString().slice(0, 10);
}

function daysAgoDate(days: number): Date {
  const d = new Date();
  d.setHours(12, 0, 0, 0);
  d.setDate(d.getDate() - days);
  return d;
}

