async function seed() {
  let targetUidResolved = targetUid;
  if (targetEmail) {
    const userRecord = await getAuth().getUserByEmail(targetEmail);
    targetUidResolved = userRecord.uid;
  }
  console.log(`Target User UID: ${targetUidResolved}${targetEmail ? ` (resolved from ${targetEmail})` : ''}`);

  const userRef = db.collection('users').doc(targetUidResolved);

  // 1. Seed User Profile
  if (targetEmail) {
    // Real existing user — only backdate their "joined" date so the seeded window doesn't
    // predate account creation. Leave displayName/email/goals/etc. exactly as they are.
    console.log("Backdating joined date (createdAt) — not touching other profile fields...");
    await userRef.set({ createdAt: Date.now() - (WINDOW_DAYS + 2) * 86400000 }, { merge: true });
  } else {
    console.log('Seeding user profile...');
    const userProfile = {
      uid: targetUidResolved,
      displayName: 'Alex Perera',
      email: 'alex@lifesync.app',
      wakeTime: '06:30',
      workStart: '09:00',
      workEnd: '17:30',
      goals: ['fitness', 'study', 'work-life-balance'],
      dailyGoals: {
        calorieTarget: 2200,
        waterTargetMl: 2500,
        stepTarget: 8500,
      },
      notificationsEnabled: true,
      createdAt: Date.now() - (WINDOW_DAYS + 2) * 86400000,
    };
    await userRef.set(userProfile, { merge: true });
  }

  // 2. Seed Habits
  console.log('Seeding habits...');
  const habitsBatch = db.batch();
  for (const h of SAMPLE_HABITS) {
    const habitRef = userRef.collection('habits').doc(h.id);
    habitsBatch.set(habitRef, {
      id: h.id,
      title: h.title,
      preferredTime: h.preferredTime,
      recurring: h.recurring,
      daysOfWeek: h.daysOfWeek,
      createdAt: Timestamp.fromMillis(Date.now() - h.ageDays * 86400000),
    });
  }
  await habitsBatch.commit();

  // 3. Seed WINDOW_DAYS Days of Habit Logs
  console.log(`Seeding ${WINDOW_DAYS} days of habit completion logs...`);
  const logsBatch = db.batch();
  const allLogs: { habitId: string; date: string; completedAt: string | null; success: boolean }[] = [];

  for (let day = WINDOW_DAYS; day >= 0; day--) {
    const dateObj = daysAgoDate(day);
    const dateStr = formatDate(dateObj);
    const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;

    for (const h of SAMPLE_HABITS) {
      const hourOffset = isWeekend ? (Math.random() > 0.5 ? 1 : 0) : 0;
      const completionHour = h.preferredHour + hourOffset;
      const isSuccess = Math.random() < h.consistency;

      const completedAt = isSuccess
        ? `${String(completionHour).padStart(2, '0')}:${String(Math.floor(Math.random() * 45)).padStart(2, '0')}`
        : null;

      const logId = `${h.id}_${dateStr}`;
      const logRef = userRef.collection('logs').doc(logId);
      const logData = {
        id: logId,
        habitId: h.id,
        date: dateStr,
        completedAt,
        success: isSuccess,
      };

      logsBatch.set(logRef, logData);
      allLogs.push(logData);
    }
  }
  await logsBatch.commit();

  // 4. Seed WINDOW_DAYS Days of Health Logs
  console.log(`Seeding ${WINDOW_DAYS} days of health logs (sleep, steps, water)...`);
  const healthBatch = db.batch();
  const sleepRecords: number[] = [];

  for (let day = WINDOW_DAYS; day >= 0; day--) {
    const dateObj = daysAgoDate(day);
    const dateStr = formatDate(dateObj);
    const isWeekend = dateObj.getDay() === 0 || dateObj.getDay() === 6;

    const sleepHours = Number((isWeekend ? 7.8 + Math.random() * 0.8 : 6.8 + Math.random() * 1.2).toFixed(1));
    const waterMl = Math.round((2200 + (Math.random() * 800 - 300)) / 100) * 100;
    const steps = Math.round(isWeekend ? 6500 + Math.random() * 5000 : 7500 + Math.random() * 4000);

    sleepRecords.push(sleepHours);

    const healthRef = userRef.collection('healthLogs').doc(dateStr);
    healthBatch.set(healthRef, {
      id: dateStr,
      date: dateStr,
      sleepHours,
      waterMl,
      steps,
    });
  }
  await healthBatch.commit();

  // 5. Seed WINDOW_DAYS Days of Food Logs
  console.log(`Seeding ${WINDOW_DAYS} days of food photo logs with nutrition analysis...`);
  const foodBatch = db.batch();
  for (let day = WINDOW_DAYS; day >= 0; day--) {
    const dateObj = daysAgoDate(day);
    const dateStr = formatDate(dateObj);
    const meal = SAMPLE_MEALS[day % SAMPLE_MEALS.length];

    const foodLogId = `food_${dateStr}_${day}`;
    const foodRef = userRef.collection('foodLogs').doc(foodLogId);
    foodBatch.set(foodRef, {
      id: foodLogId,
      date: dateStr,
      createdAt: dateObj.getTime(),
      foodItems: meal.items,
      totalCalories: meal.totalCalories,
      macros: meal.macros,
      condition: meal.condition,
      healthTip: meal.healthTip,
      confidence: meal.confidence,
    });
  }
  await foodBatch.commit();

  // 6. Pre-compute AI Recommendations using the trained ML model
  console.log('Generating & seeding live ML recommendations for all habits...');
  const recsBatch = db.batch();
  const now = new Date();
  const avgSleep = sleepRecords.slice(-14).reduce((a, b) => a + b, 0) / Math.min(sleepRecords.length, 14);

  for (const h of SAMPLE_HABITS) {
    const habitLogs = allLogs.filter((l) => l.habitId === h.id);
    const history: HourlyAttempt[] = habitLogs.map((l) => ({
      hour: Number((l.completedAt ?? h.preferredTime).split(':')[0]),
      daysAgo: Math.max(0, Math.floor((now.getTime() - new Date(l.date).getTime()) / 86400000)),
      success: l.success,
    }));

    const hourlySuccessRates = new Map<number, number>();
    for (const candHour of CANDIDATE_HOURS) {
      hourlySuccessRates.set(candHour, hourKernelSuccessRate(history, candHour, RECENCY_DECAY));
    }

    const context: MlContext = {
      isWeekend: now.getDay() === 0 || now.getDay() === 6,
      hourlySuccessRates,
      sleepHours: avgSleep,
      streakLength: 7,
      habitAgeDays: h.ageDays,
    };

    const { suggestedHour, probability } = recommendHourWithModel(context);
    const percent = Math.round(probability * 100);

    const recRef = userRef.collection('recommendations').doc(h.id);
    recsBatch.set(recRef, {
      habitId: h.id,
      suggestedTime: `${String(suggestedHour).padStart(2, '0')}:00`,
      score: Number(probability.toFixed(3)),
      reason: `ML model predicts ${percent}% success around ${String(suggestedHour).padStart(2, '0')}:00 based on your 30-day completion track record, ${avgSleep.toFixed(1)}h avg sleep, and active 7-day streak.`,
      generatedAt: now.getTime(),
    });
  }
  await recsBatch.commit();

  console.log('====================================================');
  console.log('Seeding complete! Database successfully populated:');
  console.log(`  - User Profile${targetEmail ? ` (joined date backdated ${WINDOW_DAYS + 2} days)` : ' (Alex Perera)'}`);
  console.log('  - 5 Active Habits');
  console.log(`  - ${5 * (WINDOW_DAYS + 1)} Habit Completion Logs (${WINDOW_DAYS} days)`);
  console.log(`  - ${WINDOW_DAYS + 1} Daily Health Metric Logs`);
  console.log(`  - ${WINDOW_DAYS + 1} Multimodal Food Logs`);
  console.log('  - 5 Pre-computed AI Habit Recommendations');
  console.log('====================================================');
}

seed().catch((err) => {
  console.error('Seeding error:', err);
  process.exit(1);
});